//! CodexAstraUlt: Original multi-file fixtures exercise output ownership and
//! consumer rejection without private game input or executable output.

use super::*;
use crate::discover::{self, Source};
use crate::image::Segment;

const BASE: u32 = 0x0010_0000;

// CodexAstraUlt: Two independently seeded ARM functions fill one source chunk;
// the next unit must still be pending when that chunk reaches the consumer.
fn large_program() -> Program {
    let mut words = vec![0xE1A0_0000u32; FILE_SIZE + 2];
    words[FILE_SIZE / 2] = 0xE12F_FF1E;
    words[FILE_SIZE + 1] = 0xE12F_FF1E;
    Program {
        text: Segment {
            base: BASE,
            bytes: words.into_iter().flat_map(u32::to_le_bytes).collect(),
        },
        seeds: vec![
            (BASE, Source::Entry),
            (BASE + ((FILE_SIZE / 2 + 1) * 4) as u32, Source::Entry),
        ],
        slots: None,
    }
}

// CodexAstraUlt: ARM fallback and Thumb code cover interpreter-resume discovery,
// module-relative origins and mixed headers after the first full source chunk.
fn mixed_program() -> Program {
    Program {
        text: Segment {
            base: BASE,
            bytes: [0xEE10_0F10u32, 0xE12F_FF1E, 0x4770_202A]
                .into_iter()
                .flat_map(u32::to_le_bytes)
                .collect(),
        },
        seeds: vec![(BASE, Source::Entry), (BASE + 9, Source::Entry)],
        slots: None,
    }
}

// CodexAstraUlt: Every generated byte/name must match the compatibility API,
// including overrides, module headers, origin tables and split C sources.
#[test]
fn streamed_files_match_collected_bytes_and_legacy_order() {
    let large = large_program();
    let mixed = mixed_program();
    let analyses = [discover::analyze(&large), discover::analyze(&mixed)];
    let units = [
        Unit {
            module: None,
            program: &large,
            analysis: &analyses[0],
        },
        Unit {
            module: Some("OriginalModule"),
            program: &mixed,
            analysis: &analyses[1],
        },
    ];
    let overrides = [Override {
        module: Some("OriginalModule".into()),
        address: BASE + 9,
        name: "override_thumb".into(),
        original: "original_thumb".into(),
    }];
    let collected = generate(&units, &overrides);
    let names: Vec<_> = collected.iter().map(|(name, _)| name.as_str()).collect();
    assert_eq!(
        names,
        [
            "recomp.h",
            "functions.h",
            "m001_functions.h",
            "entries.c",
            "overrides.h",
            "code000.c",
            "code001.c"
        ]
    );
    let mut streamed = BTreeMap::new();
    let mut order = Vec::new();
    generate_to(&units, &overrides, &mut |name, bytes| {
        order.push(name.to_owned());
        assert!(streamed.insert(name.to_owned(), bytes.to_vec()).is_none());
        Ok(())
    })
    .unwrap();
    let expected: BTreeMap<_, _> = collected
        .into_iter()
        .map(|(name, text)| (name, text.into_bytes()))
        .collect();
    assert_eq!(streamed, expected);
    assert!(
        order.iter().position(|name| name == "code000.c")
            < order.iter().position(|name| name == "m001_functions.h")
    );
}

// CodexAstraUlt: A failing bounded sink stops at the rejected file; later module
// headers, source chunks and final metadata must never reach that sink.
#[test]
fn rejecting_a_source_chunk_stops_before_the_next_unit() {
    let large = large_program();
    let mixed = mixed_program();
    let analyses = [discover::analyze(&large), discover::analyze(&mixed)];
    let units = [
        Unit {
            module: None,
            program: &large,
            analysis: &analyses[0],
        },
        Unit {
            module: Some("LaterModule"),
            program: &mixed,
            analysis: &analyses[1],
        },
    ];
    let mut seen = Vec::new();
    let error = generate_to(&units, &[], &mut |name, _| {
        seen.push(name.to_owned());
        if name == "code000.c" {
            Err("original sink budget exhausted".into())
        } else {
            Ok(())
        }
    })
    .unwrap_err();
    assert_eq!(error, "original sink budget exhausted");
    assert_eq!(seen, ["recomp.h", "functions.h", "code000.c"]);
}

// CodexAstraUlt: Resume discovery needs only lowering; local allocation must not
// change its collected interpreter sites for either original instruction mode.
#[test]
fn discovery_only_lowering_preserves_interpreter_resume_sites() {
    let program = mixed_program();
    let analysis = discover::analyze(&program);
    let names: BTreeMap<_, _> = analysis
        .functions
        .iter()
        .map(|(&entry, function)| {
            (
                key(entry, function.mode),
                name("", entry, function.mode == Mode::Thumb),
            )
        })
        .collect();
    let mut all_sites = Vec::new();
    for (number, (&entry, function)) in analysis.functions.iter().enumerate() {
        let interpreted = std::cell::RefCell::new(Vec::new());
        let scope = Scope {
            labels: &function.labels,
            functions: &names,
            prefix: "",
            relative: false,
            interpreted: &interpreted,
        };
        write_function(
            &mut String::new(),
            &program,
            &scope,
            entry,
            function,
            number,
        );
        let original = interpreted.take();
        write_body(
            &mut String::new(),
            &program,
            &scope,
            entry,
            function,
            number,
        );
        assert_eq!(interpreted.take(), original);
        all_sites.extend(original);
    }
    assert!(all_sites.contains(&BASE));
}
